int book_room(sqlite3 *db, int room_id, const char *from, const char *to) {
    if (sqlite3_exec(db, "BEGIN IMMEDIATE", 0, 0, 0) != SQLITE_OK) return -1;
    /* check availability, compute the rate, insert the booking ... */
    if (sqlite3_exec(db, "COMMIT", 0, 0, 0) != SQLITE_OK) {
        sqlite3_exec(db, "ROLLBACK", 0, 0, 0);   /* must not skip this on failure */
        return -1;
    }
    return 0;
}
